import axios from 'axios';

export const MY_FOLLOWERS_SESSION_ERROR = 'MY_FOLLOWERS_SESSION_ERROR'
export const MY_FOLLOWERS_COOKIE_ERROR = 'MY_FOLLOWERS_COOKIE_ERROR'
export const MY_FOLLOWERS_SUCCESS = 'MY_FOLLOWERS_SUCCESS'
export const MY_FOLLOWERS_UNKNOWN_ERROR = 'MY_FOLLOWERS_UNKNOWN_ERROR'
export const MY_FOLLOWERS_SELECTED_ROWS_CHANGE = 'MY_FOLLOWERS_SELECTED_ROWS_CHANGE'
export const MY_FOLLOWERS_MESSAGE_FORM_SHOW = 'MY_FOLLOWERS_MESSAGE_FORM_SHOW'
export const MY_FOLLOWERS_MESSAGE_FORM_HIDE = 'MY_FOLLOWERS_MESSAGE_FORM_HIDE'


export function fetchMyFollowers() {

  return dispatch => {
    //dispatch(requestMyFollowers())
    
      axios.get('https://scbm.amfdev.co.uk/api/myfollowers/')
      .then(json => catchMyFollowersSessionError(json.data, dispatch))
      .then(json => catchMyFollowersCookieError(json, dispatch))
      .then(json => doMyFollowersSuccess(json, dispatch))
      .catch(error => {

                if (error.response) {   
                      dispatch({
                          type: MY_FOLLOWERS_UNKNOWN_ERROR
                      })  
                }
      });
  }

}


function catchMyFollowersSessionError(json, dispatch) {
    //console.log('catchMyFollowersSessionError')
    if (!json.sessionValid) {
        
          dispatch({
                type: MY_FOLLOWERS_SESSION_ERROR
              });
          
        throw Error(json.myfollowersError);
    }
    
  return json;
}

function catchMyFollowersCookieError(json, dispatch) {
   //console.log('catchMyFollowersCookieError')
    if (!json.scCookiesValid) {
           dispatch({
                type: MY_FOLLOWERS_COOKIE_ERROR
              });
        throw Error(json.myfollowersError);
    }
    
  return json;
}


function doMyFollowersSuccess(json, dispatch) {
   //console.log('myfollowersSuccess')
    if (json.myfollowersSuccess) {
        dispatch({
          type: MY_FOLLOWERS_SUCCESS,
          scUsername: json.userData.scUsername
        })
    }
    
  return json;
}


export function handleMyFollowersSelectedRowsChange(selectedMyFollowers) {
    
    //console.log(selectedFollowers);
    
    return (dispatch, getState) => {
  
        //console.log('dispatch rows change selected followers')
            dispatch({
                type: MY_FOLLOWERS_SELECTED_ROWS_CHANGE,
                selectedMyFollowers: selectedMyFollowers
            })
       
        if(getState().selectedMyFollowers && getState().selectedMyFollowers.length > 0) {
            //console.log('yes selected followers more than 0')
            //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'block';
            dispatch({
                type: MY_FOLLOWERS_MESSAGE_FORM_SHOW
          })
        } else {
            //document.getElementsByClassName('rdt_TableHeader')[0].style.display = 'none';
            dispatch({
                type: MY_FOLLOWERS_MESSAGE_FORM_HIDE
          })
        }
        
    }
           
}


